{
  "decline_reason": "",
  "claims": [
    {
      "text": "A trading name does not itself own the trade mark: the Manual identifies the owner as the legal entity, not its trading style or business name.",
      "quotes": [
        {
          "ref": "TMM/Part10/1/1/1/1",
          "quote": "The owner of the trade mark right ultimately is the legal entity in question, not the trading style or business name."
        },
        {
          "ref": "TMM/Part10/1/1/1/1",
          "quote": "If a trading style or business name is included on the application in addition to the name of an applicant with legal personality (e.g. Joe Dover t/a Joe's Plumbing), those details will be entered on to the register, however it will have no bearing on the ownership of the trade mark right."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual states that cancellation ends the registration and the rights given by that registration, including exclusive use, authorising use and seeking relief under the Act for infringement.",
      "quotes": [
        {
          "ref": "TMM/Part41/1#1",
          "quote": "Cancellation of a trade mark registration results in the cessation of the registration (section 73)."
        },
        {
          "ref": "TMM/Part41/1#1",
          "quote": "After cancellation, the owner no longer has the rights given by registration of the trade mark including the exclusive right to use or to authorise the use of the trade mark and the right to seek relief under this Act if the trade mark is infringed (section 20)."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The supplied passages do not establish whether the legal entity retains any rights outside registration after cancellation, so they do not support a broader conclusion that all ownership rights either survive or end.",
      "quotes": [],
      "authority": "none"
    }
  ],
  "declined": false,
